function walkFindKey(obj,keys){if(Array.isArray(obj)){for(const x of obj){const r=walkFindKey(x,keys);if(r!==undefined)return r}}else if(obj&&typeof obj==='object'){for(const [k,v] of Object.entries(obj)){if(keys.includes(k))return v;const r=walkFindKey(v,keys);if(r!==undefined)return r}}}
function extractBracketArray(raw,key){const re=new RegExp(`["']${key}["']\\s*:\\s*\\[`,'i'),m=re.exec(raw);if(!m)throw new Error(`Key ${key} not found`);const start=m.index+m[0].lastIndexOf('[');let depth=0,inStr=false,quote='',esc=false;for(let i=start;i<raw.length;i++){const ch=raw[i];if(inStr){if(esc)esc=false;else if(ch==='\\\\')esc=true;else if(ch===quote)inStr=false;continue}if(ch==='"'||ch==="'"){inStr=true;quote=ch}else if(ch==='[')depth++;else if(ch===']'){depth--;if(depth===0)return raw.slice(start,i+1)}}throw new Error(`Unclosed array ${key}`)}
function parseEprText(raw,name){let obj=null;try{obj=JSON.parse(raw);if(Array.isArray(obj)&&obj.length&&typeof obj[0]==='object')obj=obj[0]}catch(e){}if(obj?.dataStore?.lineDataList&&obj.type){const d=parseCIQ(obj,name);if(d.metadata.dimensions!==1)throw Error('2D data requires standard Open, not 1D batch export');const curves=ciq1DCurves(d);if(curves.length!==1)throw Error('Multiple traces require standard Open');return curves[0];}let rd=obj?walkFindKey(obj,['ReData','reData']):undefined,freq=obj?walkFindKey(obj,['frequency','Frequency']):undefined;if(!rd){for(const key of ['ReData','reData'])try{const t=extractBracketArray(raw,key),re=/\[\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*,\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*\]/g;rd=[];let m;while((m=re.exec(t)))rd.push([Number(m[1]),Number(m[2])]);if(rd.length)break}catch(e){}}if(freq===undefined){const m=raw.match(/["']frequency["']\s*:\s*["']?\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)/i);if(m)freq=Number(m[1])}if(!Array.isArray(rd)||!rd.length)throw new Error(`${name}: ReData not found`);const B=[],y=[];for(const p of rd)if(Array.isArray(p)&&p.length>=2){B.push(Number(p[0]));y.push(Number(p[1]))}freq=Number(freq);if(!Number.isFinite(freq)||freq<=0)throw new Error(`${name}: invalid frequency`);return{name:name.replace(/\.[^.]+$/,''),B,y,freq,source:name}}
function stripBes3tValue(v){let s=String(v??'').trim();if((s.startsWith("'")&&s.endsWith("'"))||(s.startsWith('"')&&s.endsWith('"')))s=s.slice(1,-1);return s.trim()}
function parseBes3tDsc(text,name='descriptor.DSC'){const lines=String(text).replace(/\r/g,'').split('\n'),joined=[];for(let i=0;i<lines.length;i++){let line=lines[i];while(/\\\s*$/.test(line)&&i+1<lines.length)line=line.replace(/\\\s*$/,'')+lines[++i];joined.push(line)}const p={};for(const raw of joined){const line=raw.trim();if(!line||line.startsWith('*')||line.startsWith('#'))continue;const m=line.match(/^([^\s]+)\s+(.*)$/);if(!m)continue;p[m[1].trim().toUpperCase()]=stripBes3tValue(m[2].trim())}const n=(k,d=NaN)=>{const v=Number.parseFloat(p[k]);return Number.isFinite(v)?v:d};const xpts=Math.trunc(n('XPTS')),ypts=Math.trunc(n('YPTS',1)),zpts=Math.trunc(n('ZPTS',1));if(!Number.isFinite(xpts)||xpts<2)throw new Error(`${name}: invalid XPTS`);if(ypts!==1||zpts!==1)throw new Error(`${name}: only 1D BES3T is supported (YPTS=1, ZPTS=1)`);const expt=(p.EXPT||'CW').toUpperCase();if(expt&&!expt.includes('CW'))throw new Error(`${name}: only CW BES3T is supported`);const ikkf=(p.IKKF||'REAL').toUpperCase(),ikkfParts=ikkf.split(',').map(v=>v.trim()).filter(Boolean);if(ikkfParts.length!==1||ikkfParts[0]!=='REAL')throw new Error(`${name}: only single-channel REAL BES3T is supported`);const xtyp=(p.XTYP||'IDX').toUpperCase();if(xtyp!=='IDX')throw new Error(`${name}: only linear XTYP=IDX axes are supported in this version`);const xmin=n('XMIN'),xwid=n('XWID');if(!Number.isFinite(xmin)||!Number.isFinite(xwid))throw new Error(`${name}: XMIN/XWID missing or invalid`);const irfmt=(p.IRFMT||'D').toUpperCase().split(',')[0].trim(),bseq=(p.BSEQ||'BIG').toUpperCase();if(!['BIG','LIT'].includes(bseq))throw new Error(`${name}: unsupported BSEQ ${bseq}`);if(!['D','F','I','S'].includes(irfmt))throw new Error(`${name}: unsupported IRFMT ${irfmt}`);return{params:p,xpts,xmin,xwid,xunit:stripBes3tValue(p.XUNI||'G'),irfmt,bseq}}
function bes3tFrequencyGHz(params){let v=Number.parseFloat(params.MWFQ);if(!Number.isFinite(v)||v<=0)return null;if(v>1e7)return v/1e9;if(v>100)return v/1000;return v}
function readBes3tBinary(buffer,desc,name='spectrum.DTA'){const bytes={D:8,F:4,I:4,S:2}[desc.irfmt],need=desc.xpts*bytes;if(buffer.byteLength<need)throw new Error(`${name}: DTA contains ${buffer.byteLength} bytes; ${need} required by XPTS/IRFMT`);const dv=new DataView(buffer),little=desc.bseq==='LIT',y=new Array(desc.xpts);for(let i=0;i<desc.xpts;i++){const o=i*bytes;switch(desc.irfmt){case'D':y[i]=dv.getFloat64(o,little);break;case'F':y[i]=dv.getFloat32(o,little);break;case'I':y[i]=dv.getInt32(o,little);break;case'S':y[i]=dv.getInt16(o,little);break}}return y}
async function parseBes3tFiles(fileList){const groups=new Map();for(const f of [...fileList]){const m=f.name.match(/^(.*)\.(dsc|dta)$/i);if(!m)continue;const base=m[1],key=base.toLowerCase();if(!groups.has(key))groups.set(key,{base});groups.get(key)[m[2].toLowerCase()]=f}const curves=[],warnings=[];for(const g of groups.values()){if(!g.dsc||!g.dta){warnings.push(`${g.base}: missing ${g.dsc?'DTA':'DSC'}`);continue}try{const desc=parseBes3tDsc(await g.dsc.text(),g.dsc.name),y=readBes3tBinary(await g.dta.arrayBuffer(),desc,g.dta.name),B0=new Array(desc.xpts);for(let i=0;i<desc.xpts;i++)B0[i]=desc.xmin+desc.xwid*i/(desc.xpts-1);const B=B0.map(v=>bes3tFieldToGauss(v,desc.xunit)),freq=bes3tFrequencyGHz(desc.params);curves.push({name:g.base,B,y,freq,source:`${g.dsc.name} + ${g.dta.name}`,sourceType:'BES3T'})}catch(err){warnings.push(`${g.base}: ${err.message}`)}}if(!curves.length)throw new Error(warnings.length?warnings.join(' | '):'No valid .DSC + .DTA pairs selected');return{curves,warnings}}

async function parseMixedDataFiles(fileList){const files=[...fileList],ordinary=[],curves=[],warnings=[],types=new Set();const companion2D=new Set();const add=d=>{const cfg=TwoD.defaults(d),{v,p}=TwoD.model(d,cfg),freqs=(d.metadata.frequencies||[]).map(Number).filter(v=>Number.isFinite(v)&&v>0),freq=d.metadata.MWFQ?bes3tFrequencyGHz(d.metadata):freqs.length?mean(freqs):null;curves.push({name:d.name,B:v.x.values.slice(),y:p.x.slice(),freq,source:d.name,xAxis:{name:v.x.name,unit:v.x.unit},matrix:d});types.add('2D');};
for(const f of files.filter(f=>/\.dsc$/i.test(f.name))){const base=f.name.replace(/\.dsc$/i,'').toLowerCase();for(const x of files)if(x.name.replace(/\.[^.]+$/,'').toLowerCase()===base)companion2D.add(x);try{const d=await parseBES(f,files);if(d.y.values.length>1)add(d);else{const desc={params:d.metadata},unit=d.x.unit;curves.push({name:base,B:d.x.values.map(v=>bes3tFieldToGauss(v,unit)),y:d.real[0],freq:bes3tFrequencyGHz(d.metadata),source:f.name,sourceType:'BES3T'});types.add('BES3T');}}catch(e){warnings.push(f.name+': '+e.message);}}

for(const f of files){if(companion2D.has(f))continue;if(/\.epr$/i.test(f.name)){try{const raw=await f.text();let o;try{o=JSON.parse(raw)}catch{}if(o?.dataStore?.lineDataList&&o.type){const d=parseCIQ(o,f.name);warnings.push(...d.metadata.warnings.map(w=>f.name+': '+w));if(d.metadata.dimensions===1){curves.push(...ciq1DCurves(d));types.add('EPR');}else add(d);continue;}curves.push(parseEprText(raw,f.name));types.add('EPR');}catch(e){warnings.push(f.name+': '+e.message)}}else ordinary.push(f);}
const bes=ordinary.filter(f=>/\.(dsc|dta)$/i.test(f.name));if(bes.length)try{const r=await parseBes3tFiles(bes);curves.push(...r.curves);warnings.push(...r.warnings);types.add('BES3T')}catch(e){warnings.push(e.message)}
for(const f of ordinary.filter(f=>/\.csv$/i.test(f.name)))try{curves.push(...parseMergedCSV(await f.text(),f.name));types.add('CSV')}catch(e){warnings.push(f.name+': '+e.message)}
if(!curves.length)throw Error(warnings.join(' | ')||'No supported data selected');return{curves,warnings,types:[...types]};}

async function parseBatchLogicalFiles(fileList){const files=[...fileList],items=[],warnings=[],besFiles=files.filter(f=>/\.(dsc|dta)$/i.test(f.name));for(const f of files.filter(f=>/\.epr$/i.test(f.name))){try{const c=parseEprText(await f.text(),f.name);items.push({name:f.name.replace(/\.[^.]+$/,''),curve:c})}catch(e){warnings.push(e.message)}}if(besFiles.length){try{const r=await parseBes3tFiles(besFiles);for(const c of r.curves)items.push({name:c.name,curve:c});warnings.push(...r.warnings)}catch(e){warnings.push(e.message)}}for(const f of files.filter(f=>/\.csv$/i.test(f.name))){try{const a=parseMergedCSV(await f.text(),f.name),base=f.name.replace(/\.[^.]+$/,'');if(a.length===1)items.push({name:base,curve:a[0]});else a.forEach((c,i)=>items.push({name:`${base}_${c.name||i}`,curve:c}))}catch(e){warnings.push(`${f.name}: ${e.message}`)}}items.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'}));if(!items.length)throw new Error(warnings.length?warnings.join(' | '):'No valid batch data');return{items,warnings}}
