function markFrequencyOverride(sp,key){if(key==='freqMode')sp.freqOverrideExplicit=sp.freqMode!=='inherit';else if(['localFreqMode','localFreqTarget','localFreqConfirmed'].includes(key)){sp.freqMode='local';sp.freqOverrideExplicit=true;}}
function subplotTargetFrequency(sp,ids){if(sp.freqMode==='none')return null;const finite=ids.map(i=>state.rawCurves[i]?.freq).filter(v=>Number.isFinite(v)&&v>0);if(sp.freqMode==='local'){if(sp.localFreqMode==='manual')return Math.max(1e-12,finiteNum(sp.localFreqTarget)||9.85);if(!finite.length)return null;if(sp.localFreqMode==='mean')return mean(finite);return finite[0]}if($('globalFreqMode').value==='local_mean')return finite.length?mean(finite):null;return globalTargetFrequency()}
function sameFrequencyTarget(a,b){const av=Number.isFinite(a),bv=Number.isFinite(b);if(!av||!bv)return av===bv;return Math.abs(a-b)<=Math.max(1,Math.abs(a),Math.abs(b))*1e-12}
