function curveScaleLabel(c,index){if(!Number.isFinite(c.freq)||c.freq<=0)return'—';const {target,varies}=curveTargetSummary(index);if(varies)return'varies';return Number.isFinite(target)?coordinateScale(c,target).toFixed(7):'1.0000000'}
function subplotGFrequency(sp,ids){const nu=subplotTargetFrequency(sp,ids);if(!Number.isFinite(nu))return null;const missing=ids.some(i=>!Number.isFinite(state.rawCurves[i]?.freq)||state.rawCurves[i].freq<=0);if(!missing)return nu;const local=sp.freqMode==='local';return (local?sp.localFreqMode==='manual'&&sp.localFreqConfirmed:sp.freqMode!=='none'&&$('globalFreqMode').value==='manual'&&$('confirmManualFrequency').checked)?nu:null}
