function orderSelectedIds(card){return [...card.querySelectorAll('.order-item.selected')].map(e=>Number(e.dataset.curve))}
function moveCurveOrder(sp,ids,dir){if(!ids.length)return;if(dir==='top'){const a=sp.curves.filter(i=>ids.includes(i)),b=sp.curves.filter(i=>!ids.includes(i));sp.curves=[...a,...b];return}if(dir<0){for(let i=1;i<sp.curves.length;i++)if(ids.includes(sp.curves[i])&&!ids.includes(sp.curves[i-1]))[sp.curves[i-1],sp.curves[i]]=[sp.curves[i],sp.curves[i-1]]}else for(let i=sp.curves.length-2;i>=0;i--)if(ids.includes(sp.curves[i])&&!ids.includes(sp.curves[i+1]))[sp.curves[i],sp.curves[i+1]]=[sp.curves[i+1],sp.curves[i]]}
function subplotSummary(sp){const parts=[];if(sp.title.trim())parts.push(sp.title.trim());const mode=sp.twoD?({overlay:'Heatmap',heatmap:'Heatmap',contour:'Contour',surface3d:'3D surface',stack:'Stack',overlap:'Overlap',scan:'Variable scan'}[sp.mode]||'Heatmap'):(sp.mode==='stack'?'Stack':'Overlay');parts.push(sp.twoD?(sp.twoD.derivedFromCurves?sp.twoD.curveIndices.length+' curves':'1 dataset'):`${sp.curves.length} curves`,mode,sp.labelMode==='direct'?'Direct':sp.labelMode==='legend'?'Legend':sp.labelMode);return parts.join(' · ')}
function curveStyleOptions(value){
 const v=value||{},shape=v.symbol||'circle';let selected=v.style;
 if(!selected){if(v.mode==='symbols')selected=(v.filled?'filled-':'')+shape;else if(v.mode==='both')selected='solid-'+(v.filled?'filled-':'')+shape;else selected=v.lineStyle==='dashed'?'dashed-line':v.lineStyle==='dotted'?'dotted-line':'line';}
 const groups=[['Lines',['line','dashed-line','dotted-line']],['Markers',['circle','filled-circle','square','filled-square','triangle','filled-triangle','diamond','filled-diamond']],['Line + markers',['solid-circle','solid-filled-circle','solid-square','solid-filled-square','solid-triangle','solid-filled-triangle','solid-diamond','solid-filled-diamond','dashed-circle','dashed-filled-circle','dashed-square','dashed-filled-square','dashed-triangle','dashed-filled-triangle','dashed-diamond','dashed-filled-diamond','dotted-circle','dotted-filled-circle','dotted-square','dotted-filled-square','dotted-triangle','dotted-filled-triangle','dotted-diamond','dotted-filled-diamond']]];
 const lines={line:'━','dashed-line':'┄','dotted-line':'┈'},markers={circle:'○','filled-circle':'●',square:'□','filled-square':'■',triangle:'△','filled-triangle':'▲',diamond:'◇','filled-diamond':'◆'};
 const labels={...lines,...markers};
 for(const [prefix,line] of [['solid','━'],['dashed','┄'],['dotted','┈']])for(const [marker,symbol] of Object.entries(markers))labels[prefix+'-'+marker]=line+symbol;
 return groups.flatMap(([,values])=>values).map(s=>'<option value="'+s+'" '+(selected===s?'selected':'')+'>'+labels[s]+'</option>').join('');
}

