function refreshCurveColorControls(){
 document.querySelectorAll('.subplot').forEach((card,si)=>{
  const sp=state.subplots[si];if(!sp)return;
  const ordinary=[...card.querySelectorAll('.curve-style-row[data-curve]')];
  ordinary.forEach(row=>{
   const id=Number(row.dataset.curve),order=sp.curves.indexOf(id);
   if(order<0)return;
   const color=curveColor(order,sp.curves.length,sp,id);
   row.querySelector('.curve-style')?.style.setProperty('--curve-color',color);
   const input=row.querySelector('.curve-color');if(input)input.value=color;
  });
  const derived=[...card.querySelectorAll('.scan-derived-style[data-derived-id]')];
  derived.forEach((row,order)=>{
   const id=Number(row.dataset.derivedId);
   const color=curveColor(order,derived.length,sp,id);
   row.querySelector('.curve-style')?.style.setProperty('--curve-color',color);
   const input=row.querySelector('.curve-color');if(input)input.value=color;
  });
 });
}
