function clearConfig(){if(!defaultConfigSnapshot)return;const cfg=JSON.parse(defaultConfigSnapshot);cfg.subplots[0].curves=state.rawCurves.map((c,i)=>c.matrix?-1:i).filter(i=>i>=0);const mi=state.rawCurves.map((c,i)=>c.matrix?i:-1).filter(i=>i>=0);if(mi.length){if(!cfg.subplots[0].curves.length)cfg.subplots=[];for(const i of mi){const sp=newSubplotConfig(false);sp.curves=[];sp.gUseGlobal=false;sp.gShow=false;sp.twoD={index:i,settings:TwoD.defaults(state.rawCurves[i].matrix)};cfg.subplots.push(sp);}cfg.layout={...cfg.layout,rows:cfg.subplots.length,cols:1,spans:cfg.subplots.map(()=>1).join(' / ')};cfg.subplots.forEach((sp,i)=>Object.assign(sp,{gridRow:i+1,gridCol:1,rowSpan:1,colSpan:1}));} cfg.controls.groupExpression=cfg.subplots.map(sp=>sp.curves.join(',')).join(' / ');cfg.manualScales=Object.fromEntries(state.rawCurves.map((_,i)=>[i,1]));state.measureActive=false;state.measureStart=null;state.drag=null;state.lastPlotTarget=null;$('measureBtn').classList.remove('active');$('measureBtn').setAttribute('aria-pressed','false');$('plotCanvas').style.cursor='crosshair';setInteractionMode('VIEW');applyConfig(cfg);syncGroupExpression();recordHistory('Clear config');setStatus('Default config restored · imported data retained','good');}
function saveConfig(){downloadText(`${safeBaseName()}_config.json`,exportConfigPayload(collectConfig()),'application/json;charset=utf-8');logAction('Config saved')}async function loadConfigFile(file){applyConfig(JSON.parse(await file.text()),{record:true});logAction(`Config loaded: ${file.name}`)}
function saveProject(){if(!state.rawCurves.length)return alert('No data loaded');downloadText(`${safeBaseName()}.spinplot.json`,exportProjectPayload({appVersion:APP_VERSION,sourceType:state.sourceType,sourceName:state.sourceName,rawCurves:state.rawCurves,config:collectConfig(true)}),'application/json;charset=utf-8');logAction('Project saved')}
async function loadProjectFile(file){const o=JSON.parse(await file.text());const curves=parseProjectCurves(o);state.rawCurves=curves;state.dataVersion=(state.dataVersion||0)+1;state.sourceType=o.sourceType||'project';state.sourceName=o.sourceName||file.name;$('fileInfo').textContent=state.sourceName;state.subplots=[];if(o.config)applyConfig(o.config);else ensureSubplots();updateCurveTable();updateFreqTable();updateStatusBar();recordHistory('Open project');draw();logAction(`Project loaded: ${file.name}`,true);setStatus('Project loaded','good')}


function globalCorrectedCurves(target=globalTargetFrequency()){return state.rawCurves.map((c,i)=>({...c,...alignedCurve(c,i,target)}))}
function renderProjectionExports(){let box=$('projectionExportControls');if(!box){box=document.createElement('div');box.id='projectionExportControls';box.className='projection-export-controls';$('exportMetaBtn').parentElement.after(box);}box.innerHTML='';const plots=state.subplots.map((sp,i)=>[sp,i]).filter(([sp])=>sp.twoD);box.hidden=!plots.length;if(!plots.length)return;const l=document.createElement('label');l.textContent='Projection data: subplot';const sel=document.createElement('select');for(const [sp,i]of plots){const o=document.createElement('option');o.value=i;o.textContent='S'+(i+1)+(sp.title?' · '+sp.title:'');sel.append(o);}l.append(sel);const b=document.createElement('button');b.textContent='Export projection CSV';b.onclick=()=>{const i=Number(sel.value),sp=state.subplots[i];preparePlotModel();let matrix;try{matrix=subplotMatrix(sp)}catch(e){setStatus(e.message,'bad');return}downloadText(`${safeBaseName()}_S${i+1}_projections.csv`,TwoD.projectionCsv(matrix,sp.twoD.settings),'text/csv;charset=utf-8');logAction('Projection CSV exported');};box.append(l,b);
const scanPlots=plots.filter(([sp])=>sp.mode==='scan');
if(scanPlots.length){
 const label=document.createElement('label');
 label.textContent='Variable scan features: subplot';
 const choose=document.createElement('select');
 for(const [sp,i] of scanPlots){const option=document.createElement('option');option.value=i;option.textContent='S'+(i+1)+(sp.title?' · '+sp.title:'');choose.append(option);}
 label.append(choose);
 const button=document.createElement('button');button.textContent='Export scan features CSV';
 button.onclick=()=>{
  const i=Number(choose.value),sp=state.subplots[i];
  let dataset;try{dataset=TwoD.scanCorrelationData(subplotMatrix(sp),sp.twoD.settings);}
  catch(error){setStatus(error.message,'bad');return;}
  if(!dataset.valid){setStatus(dataset.reason||'Scan feature data unavailable','bad');return;}
  if(!dataset.points){setStatus('Select peak-to-peak amplitude, linewidth or both in Feature display.','bad');return;}
  const header=['source_index','scan_value','power_or_scan_x','amplitude','linewidth','linewidth_unit',
   'fit_amplitude','residual_amplitude','fit_linewidth','residual_linewidth','used_in_amplitude_fit','used_in_linewidth_fit'];
  const amp=new Map(dataset.amplitudeFit?.valid?dataset.amplitudeFit.points.map(p=>[p.index,p]):[]);
  const width=new Map(dataset.linewidthFit?.valid?dataset.linewidthFit.points.map(p=>[p.index,p]):[]);
  const rows=[header.join(',')];
  for(const p of dataset.points){
   const a=amp.get(p.index),w=width.get(p.index);
   rows.push([p.index,p.scan,p.x,p.amplitude,p.linewidth,dataset.axisUnit,
    a?.fitted??'',a?.residual??'',w?.fitted??'',w?.residual??'',a?'yes':'no',w?'yes':'no'].join(','));
  }
  for(const [type,fit] of [['amplitude',dataset.amplitudeFit],['linewidth',dataset.linewidthFit]]){
   if(!fit)continue;
   rows.push('# '+type+' fit: '+(fit.valid?
     JSON.stringify({model:fit.model,parameters:fit.parameters,rmse:fit.rmse,r2:fit.r2,warning:fit.warning}):
     (fit.reason||'Unavailable')));
  }
  downloadText(`${safeBaseName()}_S${i+1}_scan_features.csv`,rows.join('\n'),'text/csv;charset=utf-8');
  logAction('Variable scan features and fit results exported');
 };
 box.append(label,button);
}
}
function renderExportCanvas(){const d=getDesignSize(),dpi=currentDpi(),scale=dpi/96,c=document.createElement('canvas');renderPlot(c,d.width,d.height,scale,true);return{canvas:c,design:d,dpi,scale}}
async function makeCurrentFigureBlob(){const fmt=$('imageFormat').value;if(fmt==='svg'||fmt==='pdf'){const design=getDesignSize(),scene=vectorScene(design,document.createElement('canvas').getContext('2d'),renderPlot),svg=svgFromScene(scene);const blob=fmt==='svg'?new Blob([svg],{type:'image/svg+xml'}):await pdfFromSvg({svg,design});return{blob,ext:fmt,dpi:currentDpi()}}const{canvas,design,dpi}=renderExportCanvas();const q=clamp(Number($('imageQuality').value)||.95,.1,1);let blob,ext=fmt;if(fmt==='png'||fmt==='jpeg'||fmt==='webp'){blob=await canvasBlob(canvas,fmt==='jpeg'?'image/jpeg':fmt==='webp'?'image/webp':'image/png',q);if(fmt==='png')blob=await pngWithDpi(blob,dpi);if(fmt==='jpeg'){blob=await jpegWithDpi(blob,dpi);ext='jpg'}}else if(fmt==='bmp')blob=bmpBlob(canvas,dpi);else if(fmt==='tiff')blob=tiffBlob(canvas,dpi);return{blob,ext,dpi}}
async function exportFigure(){if(!state.rawCurves.length)return alert('No data loaded');try{const base=safeBaseName(),r=await makeCurrentFigureBlob();downloadBlob(`${base}.${r.ext}`,r.blob);logAction(`Figure exported: ${base}.${r.ext}${['svg','pdf'].includes(r.ext)?' (vector)':` (${r.dpi} DPI)`}`)}catch(e){setStatus(e.message,'bad');logAction('Export error: '+e.message)}}

function batchLog(msg,clear=false){const e=$('batchLog');if(clear)e.textContent='';e.textContent+=(e.textContent?'\n':'')+msg;e.scrollTop=e.scrollHeight}
function openBatchDialog(){const d=$('batchDialog');d.classList.add('show');d.setAttribute('aria-hidden','false');batchLog('Select data files and a SpinPlot config.',true)}function closeBatchDialog(){const d=$('batchDialog');d.classList.remove('show');d.setAttribute('aria-hidden','true')}
function configDataIndices(cfg){const set=new Set();for(const sp of cfg?.subplots||[])for(const i of sp.curves||[])if(Number.isInteger(Number(i)))set.add(Number(i));return[...set].sort((a,b)=>a-b)}
function batchPrefix(name){const i=name.indexOf('_');return i>0?name.slice(0,i):name}
function cloneJson(x){return JSON.parse(JSON.stringify(x))}
async function writeBatchOutput(dir,name,blob){if(dir){const h=await dir.getFileHandle(name,{create:true}),w=await h.createWritable();await w.write(blob);await w.close()}else{downloadBlob(name,blob);await new Promise(r=>setTimeout(r,120))}}
function buildBatchJobs(parsed,cfg){const idx=configDataIndices(cfg),single=idx.length<=1;if(!idx.length||idx.some(i=>i<0))throw new Error('Config must reference valid curve indices');if(single)return parsed.items.map(item=>({name:item.name,curves:[item.curve],sources:[item.curve.source],single:true}));const groups=new Map();for(const item of parsed.items){const at=item.name.indexOf('_');if(at<1||at===item.name.length-1)throw new Error(`${item.name}: expected sample_role name`);const sample=item.name.slice(0,at),role=item.name.slice(at+1);if(!groups.has(sample))groups.set(sample,new Map());if(groups.get(sample).has(role))throw new Error(`${sample}: duplicate role ${role}`);groups.get(sample).set(role,item)}const roles=[...groups.values()][0];const expected=[...roles.keys()].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}));if(expected.length!==Math.max(...idx)+1)throw new Error(`Expected ${Math.max(...idx)+1} roles, found ${expected.length}`);const jobs=[];for(const [name,map] of groups){const actual=[...map.keys()].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}));if(actual.length!==expected.length||actual.some((v,i)=>v!==expected[i]))throw new Error(`${name}: role mismatch; expected ${expected.join(', ')}`);const items=expected.map(role=>map.get(role));jobs.push({name,curves:items.map(x=>x.curve),sources:items.map(x=>x.curve.source),roles:expected,single:false})}return jobs}
async function runBatchPlot(){if(!state.batchFiles.length||!state.batchConfig){batchLog('ERROR: data files and config are both required.');return}const parsed=await parseBatchLogicalFiles(state.batchFiles);if(parsed.warnings.length)throw new Error(`Invalid batch inputs: ${parsed.warnings.join(' | ')}`);const jobs=buildBatchJobs(parsed,state.batchConfig),signature=JSON.stringify([state.batchFiles.map(f=>[f.name,f.size,f.lastModified]),state.batchConfig,jobs.map(j=>[j.name,j.sources])]);if(state.batchPreviewSignature!==signature){state.batchPreviewSignature=signature;batchLog(`Review ${jobs.length} output figure(s):`,true);for(const w of parsed.warnings)batchLog('Warning: '+w);for(const job of jobs)batchLog(`${job.name}: ${job.sources.map((src,i)=>`${i} ${job.roles?.[i]||'single'} ← ${src}`).join(' | ')}`);batchLog('Press Run batch again to confirm this mapping.');return}state.batchPreviewSignature=null;const saved={rawCurves:state.rawCurves,sourceType:state.sourceType,sourceName:state.sourceName,config:collectConfig(true)};let dir=null;if('showDirectoryPicker'in window){try{dir=await window.showDirectoryPicker({mode:'readwrite'})}catch(e){if(e?.name==='AbortError'){batchLog('Batch cancelled.');return}}}let ok=0;try{for(let j=0;j<jobs.length;j++){const job=jobs[j];state.rawCurves=job.curves;state.dataVersion=(state.dataVersion||0)+1;state.sourceType='batch';state.sourceName=job.name;const cfg=cloneJson(state.batchConfig);cfg.ui=null;if(job.single&&Array.isArray(cfg.subplots))cfg.subplots=cfg.subplots.map(sp=>({...sp,curves:(sp.curves||[]).length?[0]:[]}));applyConfig(cfg);$('exportBaseName').value=job.name;updateCurveTable();updateFreqTable();renderSubplotUI();renderLayoutPreview();const r=await makeCurrentFigureBlob(),filename=`${job.name}.${r.ext}`;await writeBatchOutput(dir,filename,r.blob);batchLog(`${j+1}/${jobs.length}  ${job.name} → ${filename}`);ok++}}finally{state.rawCurves=saved.rawCurves;state.dataVersion=(state.dataVersion||0)+1;state.sourceType=saved.sourceType;state.sourceName=saved.sourceName;applyConfig(saved.config);$('fileInfo').textContent=state.sourceName||'No data loaded';draw()}batchLog(`Finished: ${ok}/${jobs.length} figure(s).`);logAction(`Batch plot finished: ${ok}/${jobs.length}`)}

function collectCurrentStateForHistory(){return collectConfig()}
function updateHelp(){const tip=$('helpTooltip');const show=b=>{tip.textContent=b.dataset.help||'';const r=b.getBoundingClientRect();tip.style.left=Math.max(6,Math.min(innerWidth-365,r.right+7))+'px';tip.style.top=Math.max(6,Math.min(innerHeight-100,r.top-4))+'px';tip.classList.add('show')};document.addEventListener('mouseover',e=>{const b=e.target.closest?.('.help-tip');if(b)show(b)});document.addEventListener('mouseout',e=>{const b=e.target.closest?.('.help-tip');if(b&&!b.contains(e.relatedTarget))tip.classList.remove('show')});document.addEventListener('focusin',e=>{const b=e.target.closest?.('.help-tip');if(b)show(b)});document.addEventListener('focusout',e=>{if(e.target.closest?.('.help-tip'))tip.classList.remove('show')})}
