function bindControl(id,{history=true,realign=false,log=true}={}){const e=$(id);if(!e)return;const live=()=>{if(id==='uiFont')applyUiFont();if(['canvasPreset','canvasWidth','canvasHeight','exportDpi','customDpi','imageFormat'].includes(id))updateCanvasUi();if(['baselineMode','scaleMode'].includes(id))updateProcessingVisibility();if(['globalFreqMode','targetFreq'].includes(id)){$('globalFreqManualWrap').classList.toggle('hidden',$('globalFreqMode').value!=='manual');if(id==='globalFreqMode'||$('globalFreqMode').value==='manual')syncGlobalFrequencyMode();updateFreqTable()}scheduleDraw()};e.addEventListener('input',live);e.addEventListener('change',()=>{live();if(id==='globalYScale'){for(const sp of state.subplots)if(!sp.yScale||sp.yScale==='inherit'){try{fitSubplotYRange(sp,e.value)}catch(err){setStatus(err.message,'bad');}}renderSubplotUI();}if(history)recordHistory('Changed '+id);if(log)logAction(id+' = '+(e.type==='checkbox'?e.checked:e.value))})}
function clearAllData(){state.rawCurves=[];state.dataVersion=(state.dataVersion||0)+1;state.sourceType='';state.sourceName='';state.manualScales={};state.subplots=[];state.subplots=[newSubplotConfig(false)];state.layout={...state.layout,rows:1,cols:1,spans:'1'};state.noiseDraft=null;state.drag=null;state.hoveredSubplot=null;state.lastPlotTarget=null;state.plotRegions=[];state.history=[];state.historyIndex=-1;$('fileInfo').textContent='No data loaded';$('dataFiles').value='';$('layoutSpans').value='1';renderSubplotUI();renderLayoutPreview();updateCurveTable();updateFreqTable();recordHistory('Clear all data');draw();}
function appendOpenedData(curves,type,name){if(!curves.length)return;if(!state.rawCurves.length){clearAndLoadData(curves,type,name);return;}const start=state.rawCurves.length;state.rawCurves.push(...curves);state.dataVersion=(state.dataVersion||0)+1;state.sourceType=type;state.sourceName=state.rawCurves.length+' spectra';$('fileInfo').textContent=state.sourceName;const incoming=curves.map((c,i)=>[c,start+i]),ordinary=incoming.filter(([c])=>!c.matrix).map(([,i])=>i),added=[];for(const ids of ordinaryAxisGroups(ordinary)){const sp=newSubplotConfig(false);sp.curves=ids;added.push(sp);}for(const [c,i]of incoming.filter(([c])=>c.matrix)){const sp=newSubplotConfig(false);sp.curves=[];sp.gUseGlobal=false;sp.gShow=false;sp.twoD={index:i,settings:TwoD.defaults(c.matrix)};added.push(sp);}let row=Math.max(state.layout.rows,...state.subplots.map(sp=>sp.gridRow+sp.rowSpan-1));const spans=parseGridSpans(state.layout.spans||'1');for(const sp of added){Object.assign(sp,{gridRow:++row,gridCol:1,rowSpan:1,colSpan:state.layout.cols});state.subplots.push(sp);spans.push([state.layout.cols]);}state.layout.rows=row;state.layout.spans=spansToText(spans);$('layoutSpans').value=state.layout.spans;renderSubplotUI();renderLayoutPreview();updateCurveTable();updateFreqTable();updateStatusBar();recordHistory('Append data');draw();logAction('New data appended in '+added.length+' subplot(s)');}
function ordinaryAxisGroups(ids){const groups=new Map();for(const i of ids){const a=state.rawCurves[i].xAxis,key=a?axisKind(a)+':'+a.unit:'field:G';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(i);}return [...groups.values()];}
function clearAndLoadData(curves,type,name){state.rawCurves=curves;state.dataVersion=(state.dataVersion||0)+1;state.sourceType=type;state.sourceName=name;$('fileInfo').textContent=name;state.manualScales={};$('confirmManualFrequency').checked=false;const expected=parseGridSpans(state.layout.spans||'1').reduce((n,r)=>n+r.length,0);setSubplotCount(expected);state.subplots.forEach(sp=>{delete sp.twoD;sp.curves=curves.map((c,i)=>c.matrix?-1:i).filter(i=>i>=0);sp.noiseRegions='';sp.measurements=[];sp.annotations=[];sp.annotationsEnabled=false;sp.localFreqConfirmed=false;});const groups=ordinaryAxisGroups(curves.map((c,i)=>c.matrix?-1:i).filter(i=>i>=0));if(groups.length>1){state.subplots=groups.map(ids=>{const sp=newSubplotConfig(false);sp.curves=ids;return sp;});state.layout.rows=groups.length;state.layout.cols=1;state.layout.spans=groups.map(()=>1).join(' / ');$('layoutSpans').value=state.layout.spans;}const matrices=curves.map((c,i)=>c.matrix?i:-1).filter(i=>i>=0);if(matrices.length){if(!curves.some(c=>!c.matrix))state.subplots=[];for(const i of matrices){const sp=newSubplotConfig(false);sp.curves=[];sp.gUseGlobal=false;sp.gShow=false;sp.twoD={index:i,settings:TwoD.defaults(curves[i].matrix)};state.subplots.push(sp);}state.layout.rows=state.subplots.length;state.layout.cols=1;state.layout.spans=state.subplots.map(()=>1).join(' / ');$('layoutSpans').value=state.layout.spans;}reflowLayoutByCurrentSpans();renderSubplotUI();renderLayoutPreview();updateCurveTable();updateFreqTable();updateStatusBar();recordHistory('Load data');draw();logAction('Annotations cleared for new data')}

function getLinkedXTarget(r,newMin,newMax){if(r.projection==='side'){const s=state.subplots[r.subplot].twoD.settings;s.yProjectionMin=newMin;s.yProjectionMax=newMax;return false;}const sp=state.subplots[r.subplot];if(sp.twoD){sp.twoD.settings.xMin=newMin;sp.twoD.settings.xMax=newMax;sp.xUseGlobal=false;sp.xMin=newMin;sp.xMax=newMax;return false;}if($('linkXAxes').checked&&sp.linkX){$('globalXMin').value=newMin;$('globalXMax').value=newMax;return true}sp.xUseGlobal=false;sp.xMin=newMin;sp.xMax=newMax;return false}
