function regionAtPoint(x,y){return state.plotRegions.find(r=>x>=r.x0&&x<=r.x0+r.pw&&y>=r.y0&&y<=r.y0+r.ph)}function subplotAtPoint(x,y){return state.plotRegions.find(r=>x>=r.cellX&&x<=r.cellX+r.cellW&&y>=r.cellY&&y<=r.cellY+r.cellH)}function toggleLog(){state.logExpanded=!state.logExpanded;$('logPanel').classList.toggle('expanded',state.logExpanded);$('logToggle').textContent=state.logExpanded?'⌄':'⌃';$('logToggle').title=state.logExpanded?'Collapse log':'Expand log';recordHistory('Toggle log')}
function clearCanvas(){draw()}

function yRegionAtPoint(x,y){return state.plotRegions.find(r=>x>=Math.max(r.cellX,r.x0-Math.min(45,r.axisHitWidth??45))&&x<r.x0&&y>=r.y0&&y<=r.y0+r.ph)}
function setYRange(r,a,b){if(r.projection==='top'){const s=state.subplots[r.subplot].twoD.settings;s.xProjectionMin=a;s.xProjectionMax=b;return;}const sp=state.subplots[r.subplot];if(sp.twoD){sp.twoD.settings.yMin=a;sp.twoD.settings.yMax=b;sp.yUseGlobal=false;sp.yMin=a;sp.yMax=b;return;}if($('linkYAxes').checked&&sp.linkY){$('globalYMin').value=a;$('globalYMax').value=b}else{sp.yUseGlobal=false;sp.yMin=a;sp.yMax=b}}
function orient2DForFit(sp){const d=subplotMatrix(sp);return sp.twoD.settings.swap?{x:d.y,y:d.x}:{x:d.x,y:d.y};}
function fitAxis(axis){const target=state.hoveredSubplot,linked=$(axis==='x'?'linkXAxes':'linkYAxes').checked;const indices=target===null?state.subplots.map((_,i)=>i):[target];for(const i of indices){const sp=state.subplots[i];if(sp.twoD&&!['scan','overlap'].includes(sp.mode)){const v=orient2DForFit(sp)[axis];sp.twoD.settings[axis+'Min']=Math.min(v.values[0],v.values.at(-1));sp.twoD.settings[axis+'Max']=Math.max(v.values[0],v.values.at(-1));}sp[axis+'Min']='';sp[axis+'Max']='';if(target===null||linked&&sp[axis==='x'?'linkX':'linkY']){$(axis==='x'?'globalXMin':'globalYMin').value='';$(axis==='x'?'globalXMax':'globalYMax').value=''}else sp[axis+'UseGlobal']=false}renderSubplotUI();recordHistory('Fit '+axis.toUpperCase());draw()}
function clearMeasurements(){if(state.drag?.type==='measure')state.drag=null;state.measureStart=null;const hasMarks=state.subplots.some(sp=>sp.measurements?.length);state.subplots.forEach(sp=>sp.measurements=[]);if(hasMarks)recordHistory('Clear measurements');draw();logAction('ΔB marks cleared');}
function toggleMeasure(){state.measureActive=!state.measureActive;if(state.drag?.type==='measure')state.drag=null;state.measureStart=null;$('measureBtn').classList.toggle('active',state.measureActive);$('measureBtn').setAttribute('aria-pressed',String(state.measureActive));$('plotCanvas').style.cursor=state.measureActive?'crosshair':'';setInteractionMode(state.measureActive?'ΔB: drag to measure':'VIEW');draw()}
function annotationB(a,nu){const g=finiteNum(a.g);return a.source==='g'?(g>0&&Number.isFinite(nu)?BFromG(g,nu):NaN):finiteNum(a.x)}
function wireAnnotations(card,sp){
 sp.annotations??=[];const details=card.querySelector('[data-annotation-details]'),box=card.querySelector('[data-annotations]');
 details.addEventListener('toggle',()=>{if(details.isConnected)sp.annotationsOpen=details.open});
 const nu=displayFrequency(sp,processedSubplot(sp));const deleteButton=card.querySelector('[data-annotation-delete]');deleteButton.disabled=true;
 sp.annotations.forEach((a,i)=>{
  const row=document.createElement('div');row.className='annotation-entry';
  const B=annotationB(a,nu),g=B>0&&Number.isFinite(nu)?gFromB(B,nu):NaN;
  row.innerHTML='<div class="grid2"><label>x<input data-a="x" type="number" step="any"></label><label>g<input data-a="g" type="number" step="any"></label></div><div class="grid2"><label>Label<input data-a="label" type="text"></label><label>Y Position (0–1)<input data-a="y" type="number" min="0" max="1" step=".01"></label></div>';
  const inputs=Object.fromEntries([...row.querySelectorAll('[data-a]')].map(el=>[el.dataset.a,el]));
  inputs.x.value=Number.isFinite(B)?B:'';inputs.g.value=Number.isFinite(g)?g:'';
  inputs.label.value=a.label||'';inputs.y.value=a.y??.2;
  for(const [key,el] of Object.entries(inputs)){
   el.addEventListener('input',()=>{if(key==='y'&&el.value!==''&&(Number(el.value)<0||Number(el.value)>1||!Number.isFinite(Number(el.value)))){el.setCustomValidity('Enter a value from 0 to 1');el.reportValidity();return}el.setCustomValidity('');a[key]=key==='label'?el.value:el.value===''?'':Number(el.value);
    if(key==='x'||key==='g'){a.source=key;const b=annotationB(a,nu);
     if(key==='x')inputs.g.value=b>0&&Number.isFinite(nu)?gFromB(b,nu):'';
     else inputs.x.value=Number.isFinite(b)?b:'';
    }scheduleDraw()});
   el.addEventListener('change',()=>recordHistory('Annotation'));
  }
  row.addEventListener('click',()=>{box.querySelectorAll('.annotation-entry').forEach(r=>r.classList.remove('selected'));row.classList.add('selected');box.dataset.selected=String(i);deleteButton.disabled=false});
  box.appendChild(row);
 });
 card.querySelector('[data-annotation-add]').onclick=()=>{sp.annotationsOpen=true;sp.annotations.push({source:'x',x:'',g:'',label:'',y:.2});recordHistory('Add annotation');renderSubplotUI();draw()};
 card.querySelector('[data-annotation-delete]').onclick=()=>{const i=Number(box.dataset.selected);if(!sp.annotations.length||box.dataset.selected===undefined||!Number.isInteger(i)||i<0||i>=sp.annotations.length)return;sp.annotations.splice(i,1);sp.annotationsOpen=true;recordHistory('Delete annotation');renderSubplotUI();draw()};
 card.querySelector('[data-annotation-clear]').onclick=()=>{sp.annotations=[];sp.annotationsOpen=true;recordHistory('Clear annotations');renderSubplotUI();draw()};
}
