function initialConfig(){$('globalFreqManualWrap').classList.toggle('hidden',$('globalFreqMode').value!=='manual');state.subplots=[];state.layout.spans='1';state.layout.rows=1;state.layout.cols=1;state.layout.gapX=0;state.layout.gapY=20;$('layoutSpans').value='1';$('layoutPreset').value='1x1';$('layoutGapX').value=0;$('layoutGapY').value=20;state.subplots=[newSubplotConfig(false)];state.subplots[0].curves=[];Object.assign(state.subplots[0],{gridRow:1,gridCol:1,rowSpan:1,colSpan:1});renderSubplotUI();renderLayoutPreview();syncGroupExpression();recordHistory('Initial state')}

organizeGlobalUI();populateFonts();initEvents();initialConfig();updateFreqTable();updateCurveTable();renderPalettePicker();updateCanvasUi();updateStatusBar();draw();updateUndoRedo();defaultConfigSnapshot=JSON.stringify(collectConfig(true));

// Capture UI state once; numerical processing completes before the renderer runs.
function renderPlot(canvas,w,h,scale=1,isExport=false){
 const model=preparePlotModel().map(m=>({...m,matrix:m.sp.twoD?subplotMatrix(m.sp):null,gConfig:subplotGConfig(m.sp),frequency:displayFrequency(m.sp,m.curves),colors:m.curves.map((c,i)=>curveColor(i,m.curves.length,m.sp,c.index??i))}));
 for(const m of model){m.sp={...m.sp,annotations:(m.sp.annotations||[]).map(a=>({...a,displayCoordinate:annotationB(a,(m.sp.twoD||(m.sp.derivedFromTwoD&&axisKind(m.sp.derivedXAxis)!=='field'))?null:m.frequency)}))};}
 const controls=Object.fromEntries([...document.querySelectorAll('[id]')].map(e=>[e.id,{value:e.value,checked:e.checked}]));
 const view={layout:state.layout,noiseDraft:state.noiseDraft,drag:state.drag,plotRegions:state.plotRegions};
 return renderFigure(canvas,w,h,scale,isExport,{model,cells:layoutCells(),controls,view,style:{theme:plotTheme(),font:getFont('plotFont','customPlotFont','Arial')}});
}

function exportGlobalCsv(){if(!state.rawCurves.length)return;let target=globalTargetFrequency();if($('globalFreqMode').value==='local_mean'){const summaries=state.rawCurves.map((_,i)=>curveTargetSummary(i)),first=summaries[0]?.target??null;if(summaries.some(s=>s.varies)||summaries.some(s=>!sameFrequencyTarget(s.target,first))){setStatus('Local mean uses different targets across subplots; use Display CSV for per-subplot aligned data.','bad');return;}target=first;}downloadText(`${safeBaseName()}_global.csv`,globalCurvesCSV(globalCorrectedCurves(target)),'text/csv;charset=utf-8');logAction('Global corrected CSV exported');}
function exportDisplayCsv(){if(!state.rawCurves.length)return;downloadText(`${safeBaseName()}_display.csv`,displayCurvesCSV(state.subplots.map(sp=>({sp,curves:processedSubplot(sp)})),collectControls()),'text/csv;charset=utf-8');logAction('Subplot display CSV exported');}
function exportMeta(){downloadText(`${safeBaseName()}_freqmeta.csv`,frequencyMetadataCSV(state.rawCurves,globalTargetFrequency(),collectControls()),'text/csv;charset=utf-8');logAction('Frequency metadata exported');}
